			title = "Résumé",
			text = [=[Zul'Alai est l'un des morts d'{link:the-drowned-city}I'lalai{/link} qui ne sont pas restés dans la tombe. Quand la cité remonta de la mer, il remonta avec elle. Il est parmi les premiers à barrer le chemin de ses ruines, et ceux qui l'ont affronté disent qu'il devient toujours plus sauvage à mesure que sa fin approche. Son nom fait écho au nom de la cité elle-même.]=],
		},
		{
			title = "Non consigné",
			text = [=[Qui était Zul'Alai de son vivant, et ce qui le retient en ce monde, aucune tablette lue jusqu'ici ne l'a dit.]=],
		},
	},
	bonds = {
		{ id = "zin-aka", name = "Zin'aka", note = "défend les ruines avec lui" },
	},
})

